namespace Forge.Services;

public static class NotificationNavigation
{
    public static async Task OpenPendingAsync()
    {
        var route = Preferences.Get("pending_notification_route", "");
        if (string.IsNullOrEmpty(route) || Application.Current?.Windows.FirstOrDefault()?.Page is not AppShell) return;
        Preferences.Remove("pending_notification_route");
        // Only destinations generated by FORGE can be opened by a notification.
        if (route is not ("friendRequests" or "achievements") &&
            !System.Text.RegularExpressions.Regex.IsMatch(route, @"^(profile\?userId=[a-zA-Z0-9]+|workoutDetail\?workoutId=[a-zA-Z0-9]+&source=pocketbase)$")) return;
        try { await Shell.Current.GoToAsync(route); }
        catch (Exception ex) { System.Diagnostics.Debug.WriteLine($"[Notification navigation] {ex.GetType().Name}"); }
    }
}
